<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import AdminLayout from '@/Layouts/AdminLayout.vue';
import StatusBadge from '@/Components/StatusBadge.vue';
import { formatDateTime } from '@/utils/date';
const props = defineProps({ application: Object, statusLabels: Object });
const form = useForm({ status: '', admin_note: '', requested_fields: [] });
const fieldLabels = { name: 'Nama', email: 'Email', account_type: 'Jenis akun', phone: 'Nomor telepon', address: 'Alamat', institution_name: 'Nama institusi', responsible_name: 'Nama penanggung jawab', responsible_position: 'Jabatan penanggung jawab' };
const profileFields = [
    { key: 'account_type', label: 'Jenis akun', format: (value) => value === 'institution' ? 'Institusi' : value === 'individual' ? 'Individu' : null },
    { key: 'phone', label: 'Nomor telepon' },
    { key: 'address', label: 'Alamat' },
    { key: 'institution_name', label: 'Nama institusi' },
    { key: 'responsible_name', label: 'Nama penanggung jawab' },
    { key: 'responsible_position', label: 'Jabatan penanggung jawab' },
];
const reconcileForm = useForm({});
const decide = (status) => { form.status = status; form.put(route('admin.applications.update', props.application.id)); };
const reconcilePaid = () => reconcileForm.post(route('admin.applications.reconcile-paid', props.application.id));
</script>

<template>
    <Head title="Detail Permohonan" />
    <AdminLayout>
        <Link :href="route('admin.applications.index')" class="inline-flex min-h-10 items-center text-sm font-semibold text-aski-700 hover:text-aski-900 focus-visible:rounded focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-aski-700">← Kembali ke daftar permohonan</Link>
        <header class="mt-5 flex flex-wrap items-start justify-between gap-4 rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 sm:p-7">
            <div class="min-w-0"><p class="text-sm font-semibold tracking-wide text-aski-700">DETAIL PERMOHONAN #{{ application.id }}</p><h1 class="mt-1 break-words text-2xl font-bold text-aski-900 sm:text-3xl">{{ application.user.name }}</h1><a :href="`mailto:${application.user.email}`" class="mt-1 inline-block break-all text-sm text-slate-600 hover:text-aski-700">{{ application.user.email }}</a></div>
            <StatusBadge :status="application.status" :label="statusLabels[application.status]" />
        </header>
        <div v-if="application.needs_status_review" class="mt-5 rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-amber-950"><p>Status perlu ditinjau: tagihan tercatat lunas dan bukti pembayaran terverifikasi, tetapi permohonan belum berstatus selesai. Jika masa keanggotaan terkait juga tercatat, Admin dapat merekonsiliasi status. Tindakan ini dicatat dalam riwayat.</p><button v-if="application.can_reconcile_paid" type="button" class="mt-3 rounded-lg bg-aski-800 px-4 py-2 font-semibold text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2" :disabled="reconcileForm.processing" @click="reconcilePaid">{{ reconcileForm.processing ? 'Memproses…' : 'Rekonsiliasi status selesai' }}</button><p v-if="reconcileForm.errors.application" class="mt-2 text-red-800">{{ reconcileForm.errors.application }}</p></div>
        <section v-if="application.invoice" class="card mt-5 flex flex-wrap items-center justify-between gap-4 p-5"><div class="min-w-0"><h2 class="font-bold text-aski-900">Tagihan {{ application.invoice.number }}</h2><p class="mt-1 text-sm text-slate-600">Status: {{ application.invoice.status === 'paid' ? 'Dibayar' : 'Belum dibayar' }}<span v-if="application.invoice.membership"> · Masa aktif {{ application.invoice.membership.starts_at }} – {{ application.invoice.membership.ends_at }}</span></p><p v-if="application.invoice.payments.length" class="mt-1 text-sm text-slate-600">Pembayaran: {{ application.invoice.payments.some((payment) => payment.status === 'verified') ? 'Terverifikasi' : 'Menunggu pemeriksaan' }}</p></div><Link :href="route('admin.invoices.view', application.invoice.id)" class="inline-flex min-h-10 shrink-0 items-center font-semibold text-aski-700">Buka tagihan →</Link></section>
        <section class="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1.1fr)_minmax(20rem,0.9fr)]">
            <div class="space-y-6">
                <section class="card overflow-hidden p-0"><div class="border-b border-slate-100 bg-slate-50/70 px-5 py-4 sm:px-6"><h2 class="text-lg font-bold text-aski-900">Profil Pemohon</h2><p class="mt-1 text-sm text-slate-600">Informasi kontak dan data akun yang terhubung dengan permohonan ini.</p></div><dl class="grid gap-x-8 sm:grid-cols-2">
                    <div class="border-b border-slate-100 px-5 py-4 sm:px-6"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Nama lengkap</dt><dd class="mt-1 break-words text-sm font-medium text-slate-900">{{ application.user.name || 'Belum diisi' }}</dd></div>
                    <div class="border-b border-slate-100 px-5 py-4 sm:px-6"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Email</dt><dd class="mt-1 break-all text-sm font-medium text-slate-900">{{ application.user.email || 'Belum diisi' }}</dd></div>
                    <div v-for="field in profileFields" :key="field.key" class="border-b border-slate-100 px-5 py-4 last:border-0 sm:px-6"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">{{ field.label }}</dt><dd class="mt-1 whitespace-pre-line break-words text-sm font-medium text-slate-900">{{ field.format ? field.format(application.user.member_profile?.[field.key]) || 'Belum diisi' : application.user.member_profile?.[field.key] || 'Belum diisi' }}</dd></div>
                </dl></section>
                <section v-if="application.latest_revision" class="card p-5 sm:p-6"><div class="flex flex-wrap items-start justify-between gap-2"><div><h2 class="text-lg font-bold text-aski-900">Data Revisi Terbaru</h2><p class="mt-1 text-sm text-slate-600">Data yang dikirim Member saat pengajuan ulang.</p></div><span class="rounded-full bg-aski-50 px-3 py-1 text-xs font-semibold text-aski-800">Snapshot pengajuan</span></div><dl class="mt-4 grid gap-3 sm:grid-cols-2"><div v-for="(value, key) in application.latest_revision.revision_data.submitted_profile" :key="key" class="rounded-lg bg-slate-50 p-3"><dt class="text-xs font-medium text-slate-500">{{ fieldLabels[key] || key }}</dt><dd class="mt-1 break-words text-sm font-medium text-slate-900">{{ value || 'Belum diisi' }}</dd></div></dl><p class="mt-3 text-xs text-slate-500">Snapshot ini mencatat data saat diajukan ulang; profil di atas menampilkan data terkini.</p></section>
            </div>
            <div class="space-y-6">
                <section class="card p-5 sm:p-6"><h2 class="text-lg font-bold text-aski-900">Keputusan Admin</h2><p v-if="application.status === 'submitted'" class="mt-1 text-sm text-slate-600">Tinjau profil pemohon, lalu pilih tindakan.</p><div v-if="application.status === 'submitted'" class="mt-5"><label for="application-admin-note" class="text-sm font-medium text-aski-900">Catatan untuk Member</label><textarea id="application-admin-note" v-model="form.admin_note" rows="4" placeholder="Wajib untuk revisi atau penolakan" class="mt-1 w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"></textarea><p v-if="form.errors.admin_note" role="alert" class="mt-1 text-sm text-red-700">{{ form.errors.admin_note }}</p><fieldset class="mt-5"><legend class="text-sm font-semibold text-aski-900">Data yang perlu diperbaiki <span class="font-normal text-slate-500">(pilih untuk permintaan revisi)</span></legend><div class="mt-3 grid gap-2 sm:grid-cols-2 xl:grid-cols-1 2xl:grid-cols-2"><label v-for="(label, key) in fieldLabels" :key="key" class="flex min-h-10 cursor-pointer items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm text-slate-700 hover:bg-slate-50"><input v-model="form.requested_fields" type="checkbox" :value="key" class="rounded border-slate-300 text-aski-700 focus:ring-aski-500">{{ label }}</label></div></fieldset><p v-if="form.errors.requested_fields" role="alert" class="mt-2 text-sm text-red-700">{{ form.errors.requested_fields }}</p><div class="mt-5 grid gap-2 sm:grid-cols-3"><button class="btn-primary min-h-11" :disabled="form.processing" @click="decide('approved_waiting_payment')">Setujui</button><button class="min-h-11 rounded-lg bg-gold-400 px-4 py-2 text-sm font-semibold text-aski-900 disabled:opacity-50" :disabled="form.processing" @click="decide('revision')">Minta Revisi</button><button class="min-h-11 rounded-lg bg-red-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" :disabled="form.processing" @click="decide('rejected')">Tolak</button></div></div><p v-else class="mt-4 rounded-lg bg-slate-50 p-3 text-sm text-slate-600">Permohonan ini telah diproses. Status dan catatan keputusan tercatat pada riwayat.</p></section>
                <section class="card p-5 sm:p-6"><h2 class="text-lg font-bold text-aski-900">Riwayat Status</h2><ol v-if="application.histories.length" class="mt-5 space-y-0"><li v-for="(history, index) in application.histories" :key="history.id" class="relative border-l-2 border-gold-400 pb-5 pl-5 last:border-transparent last:pb-0"><span class="absolute -left-[7px] top-0 h-3 w-3 rounded-full border-2 border-white bg-gold-400"></span><b class="text-sm text-slate-900">{{ statusLabels[history.status] || 'Status tidak dikenal' }}</b><p class="mt-1 text-xs text-slate-500">{{ formatDateTime(history.created_at) }}<span v-if="history.changed_by"> · {{ history.changed_by.name }}</span></p><p v-if="history.note" class="mt-2 whitespace-pre-line text-sm text-slate-700">{{ history.note }}</p></li></ol><p v-else class="mt-4 text-sm text-slate-500">Belum ada riwayat perubahan status.</p></section>
            </div>
        </section>
    </AdminLayout>
</template>
